import React, { Component } from "react";
import "./chat.css";

class ChatComponent extends Component {
  constructor(props) {
    super(props);
    this.state = {
      messages: [],
      newMessage: "",
    };
  }

  handleMessageChange = (event) => {
    this.setState({ newMessage: event.target.value });
  };

  handleSendMessage = () => {
    if (this.state.newMessage.trim() !== "") {
      const newMessage = {
        text: this.state.newMessage,
        time: new Date().toLocaleTimeString(),
      };
      this.setState(
        (prevState) => ({
          messages: [...prevState.messages, newMessage],
          newMessage: "",
        }),
        () => {
          this.messagesEnd.scrollIntoView({ behavior: "smooth" });
        }
      );
    }
  };

  render() {
    return (
      <div className="custom-chat-container">
        <div className="custom-messages-container">
          <div className="custom-messages">
            {this.state.messages.map((message, index) => (
              <div key={index} className="custom-message">
                <span className="custom-message-text">{message.text}</span>
                <span className="custom-message-time">{message.time}</span>
              </div>
            ))}
            <div ref={(el) => { this.messagesEnd = el; }} />
          </div>
        </div>
        <input
          type="text"
          className="custom-input"
          value={this.state.newMessage}
          onChange={this.handleMessageChange}
          placeholder="Type your message"
        />
        <button onClick={this.handleSendMessage} className="custom-button">
          Send
        </button>
        <button onClick={this.props.onEndChat} className="custom-end-button">
          End Chat
        </button>
      </div>
    );
  }
}

export default ChatComponent;
